<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><?php $available = $product['status_ketersediaan'] === 'tersedia' && (int) $product['stok'] > 0; ?>
<section class="container section-space"><a class="text-link back-link" href="<?= site_url('katalog') ?>"><span aria-hidden="true">←</span> Kembali ke katalog</a><div class="row g-5 align-items-start mt-1"><div class="col-md-6"><img class="detail-image" src="<?= esc(product_image($product['gambar']), 'attr') ?>" alt="<?= esc($product['nama_produk'], 'attr') ?>" width="600" height="680"><?php if (str_starts_with($product['gambar'] ?? '', 'sample-')): ?><p class="small text-muted mt-2">Ilustrasi produk contoh, bukan foto produk asli.</p><?php endif ?></div><div class="col-md-6 detail-copy"><p class="eyebrow"><?= esc($product['kategori']) ?></p><h1><?= esc($product['nama_produk']) ?></h1><p class="detail-price"><?= rupiah($product['harga']) ?></p><span class="status-pill"><?= ! $available ? 'Stok habis' : 'Stok tersedia: ' . (int) $product['stok'] ?></span><div class="product-description"><h2>Tentang produk</h2><p><?= nl2br(esc($product['deskripsi'])) ?></p></div><?php if ($available): ?><form class="detail-cart-form" method="post" action="<?= site_url('keranjang/tambah/' . $product['id']) ?>"><?= csrf_field() ?><input type="hidden" name="return_to" value="katalog/<?= esc($product['slug'], 'attr') ?>"><div><label class="form-label" for="qty">Jumlah</label><input class="form-control" id="qty" type="number" name="qty" value="1" min="1" max="<?= (int) $product['stok'] ?>" inputmode="numeric"></div><button class="btn btn-primary" type="submit">Tambah ke Keranjang</button></form><p class="small text-muted mt-3">Produk ditambahkan tanpa meninggalkan halaman ini.</p><?php else: ?><button class="btn btn-primary w-100" disabled>Stok Habis</button><?php endif ?></div></div></section>
<?= $this->endSection() ?>
